import{_ as a,a as e,c as n,b as o}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"05-代码块折叠与交互组件","description":"深入解析代码块容器的高级渲染机制、自动换行行号联动算法、代码折叠状态机与一键纯净提取复制流程。","frontmatter":{"title":"05-代码块折叠与交互组件","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"深入解析代码块容器的高级渲染机制、自动换行行号联动算法、代码折叠状态机与一键纯净提取复制流程。","tags":["组件设计","代码块"]},"headers":[],"relativePath":"posts/0-博客指南/博客的组件设计/05-代码块折叠与交互组件.md","filePath":"posts/0-博客指南/博客的组件设计/05-代码块折叠与交互组件.md"}'),t={name:"posts/0-博客指南/博客的组件设计/05-代码块折叠与交互组件.md"};function l(i,s,r,p,c,d){return e(),n("div",null,[...s[0]||(s[0]=[o(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_05-代码块折叠与交互组件" tabindex="-1">05-代码块折叠与交互组件 <a class="header-anchor" href="#_05-代码块折叠与交互组件" aria-label="Permalink to &quot;05-代码块折叠与交互组件&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>代码块是技术长文中最核心的交付产物。为了解决传统代码块横向滚动不友好、行号错位、长代码占用巨幅纵向篇幅等通病，博客在 Markdown-it 与 Shiki 编译器层面构筑了深度增强的交互容器。</p><h2 id="_1-自动换行与行号联动算法" tabindex="-1">1. 自动换行与行号联动算法 <a class="header-anchor" href="#_1-自动换行与行号联动算法" aria-label="Permalink to &quot;1. 自动换行与行号联动算法&quot;">​</a></h2><p>许多技术站点在代码换行时，行号机制容易失效，往往把折行后的每一小截都误标为新行号，造成代码阅读严重混淆：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>传统方案 (产生错位):</span></span>
<span class="line"><span>  Line 1: const longQuery = &quot;SELECT id, name FROM users</span></span>
<span class="line"><span>  Line 2:                    WHERE status = 1&quot;;  &lt;-- 错误增加行号!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>博客联动方案 (精准对齐):</span></span>
<span class="line"><span>  Line 1: const longQuery = &quot;SELECT id, name FROM users</span></span>
<span class="line"><span>                             WHERE status = 1&quot;;  &lt;-- 属于首行折行，不增加行号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>CSS 动态计数器驱动</strong>：系统采用 CSS 计数器针对每个代码行容器独立递增。当单行代码因屏幕宽度受限自然折行时，行号伪元素仅锚定在首行左侧，内部折行内容绝对不产生多余行号。</li><li><strong>全设备平滑自适应</strong>：在移动端与小屏视口下，长指令自动平滑软换行，杜绝难看的横向滚动条，保证阅读节奏顺畅。</li></ul><h2 id="_2-专有名词大小写徽标与文件标题" tabindex="-1">2. 专有名词大小写徽标与文件标题 <a class="header-anchor" href="#_2-专有名词大小写徽标与文件标题" aria-label="Permalink to &quot;2. 专有名词大小写徽标与文件标题&quot;">​</a></h2><p>代码块右上角或控制栏的标识直接映射开发者的审美与专业素养：</p><ul><li><strong>专有名词大小写规范字典</strong>：系统建立标准技术专有名词对照字典，例如将原始小写标识 <code>ts</code> 映射展示为标准的 <code>TypeScript</code>，将 <code>sh</code> 映射为 <code>Bash</code>，将 <code>json</code> 映射为 <code>JSON</code>，彻底终结以往全大写或小写混杂的粗糙感。</li><li><strong>自定义文件路径标题</strong>：支持使用中括号在首行指定完整路径，例如 <code>[src/auth/token.service.ts]</code>。解析引擎会在代码块左上方优雅呈现代码小图标与文件全路径，帮助读者建立清晰的工程上下文。</li></ul><h2 id="_3-代码折叠状态机与展开指示条" tabindex="-1">3. 代码折叠状态机与展开指示条 <a class="header-anchor" href="#_3-代码折叠状态机与展开指示条" aria-label="Permalink to &quot;3. 代码折叠状态机与展开指示条&quot;">​</a></h2><p>长篇完整工程代码往往占据数屏高度，容易阻断读者的思维主线：</p><ul><li><strong>默认展开与按需收起</strong>：代码块默认呈现完整代码，右上角提供折叠切换按钮，读者阅读到次要细节时可随时收起。</li><li><strong>展开指示条防信息丢失</strong>：代码块折叠后，容器收敛为轻量条带，底部醒目展现“已折叠代码，点击展开”指示条，读者点击任意区域即可瞬间平滑展开。</li><li><strong>末行空行原样保留</strong>：针对 Shiki 编译器默认自动剔除末尾空行的侵入式行为，解析引擎进行了代码边界补丁修复，严格保留代码末尾原本的书写间距。</li></ul><h2 id="_4-纯净代码一键提取与复制反馈" tabindex="-1">4. 纯净代码一键提取与复制反馈 <a class="header-anchor" href="#_4-纯净代码一键提取与复制反馈" aria-label="Permalink to &quot;4. 纯净代码一键提取与复制反馈&quot;">​</a></h2><p>读者点击右上角复制按钮时，交互逻辑会自动完成纯净代码提取：</p><ul><li><strong>自动剥离行号与提示符</strong>：复制事件仅提取纯净的代码字符文本，自动滤除页面渲染产生的行号数字以及终端命令首部的命令行提示符，确保读者直接粘贴即可编译运行。</li><li><strong>全局悬浮消息反馈</strong>：复制成功后，屏幕中上方弹出优雅的全局轻提示，明确反馈复制成功的动作状态。</li></ul>`,16)])])}const _=a(t,[["render",l]]);export{h as __pageData,_ as default};
